package ru.mentor.platform.identity;

import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class PasswordCompatibilityTest {
    private final PasswordCodec codec = new PasswordCodec();
    // Synthetic vector generated by lib/auth-passwords.cjs, never a user's password/hash.
    static final LegacyPasswordHash NODE_HASH = new LegacyPasswordHash("scrypt", 131072, 8, 1,
        "fSlw9mrvdWUsRSVgtryTPQ==", "ZS22lf6iPimRwOlaoGnpjdI1Fom/tRlVkxgnxUXr3pVI2yAlSTeJINHQeBXh4/Oc5n5/qOCcLl95dXrRcqufWA==");

    @Test void verifiesNodeUnicodeVectorWithoutTrimmingSpaces() {
        String encoded = codec.importLegacy(NODE_HASH);
        assertTrue(codec.matches("  Пароль😀8  ", encoded));
        assertFalse(codec.matches("Пароль😀8", encoded));
    }

    @Test void enforcesCodePointAndUtf8BoundariesWithoutReplacingMalformedUnicode() {
        assertThrows(IllegalArgumentException.class, () -> codec.encode("😀".repeat(7)));
        String eight = codec.encode("😀".repeat(8));
        assertTrue(codec.matches("😀".repeat(8), eight));
        String max = codec.encode("😀".repeat(128)); // 128 Unicode scalars, 512 UTF-8 bytes
        assertTrue(codec.matches("😀".repeat(128), max));
        assertThrows(IllegalArgumentException.class, () -> codec.encode("a".repeat(129)));
        assertThrows(IllegalArgumentException.class, () -> codec.encode("😀".repeat(128) + "a")); // 513 bytes
        assertThrows(IllegalArgumentException.class, () -> codec.encode("password\uD800"));
        assertThrows(IllegalArgumentException.class, () -> codec.encode("password\uDC00"));
        assertFalse(codec.matches("password\uD800", eight));
        assertFalse(codec.matches("😀".repeat(128) + "a", max));
    }

    @Test void saltsIndependentlyAndRejectsUntrustedLegacyParameters() {
        String first = codec.encode("synthetic-password");
        String second = codec.encode("synthetic-password");
        assertNotEquals(first, second);
        assertTrue(codec.matches("synthetic-password", first));
        assertTrue(codec.matches("synthetic-password", second));
        assertThrows(IllegalArgumentException.class, () -> codec.importLegacy(new LegacyPasswordHash("scrypt", 2, 8, 1, NODE_HASH.saltBase64(), NODE_HASH.hashBase64())));
        assertThrows(IllegalArgumentException.class, () -> codec.importLegacy(new LegacyPasswordHash("other", 131072, 8, 1, NODE_HASH.saltBase64(), NODE_HASH.hashBase64())));
        assertThrows(IllegalArgumentException.class, () -> codec.importLegacy(new LegacyPasswordHash("scrypt", 131072, 8, 1, "broken", NODE_HASH.hashBase64())));
    }
}
